        }

        /* Floating Draggable Panel */
        .drag-widget {
            position: fixed;
            z-index: 2147483647 !important; 
            background: var(--panel-bg);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            border-radius: 50%; 
            border: 2px solid var(--card-border);
            box-shadow: 0 15px 40px rgba(0, 0, 0, 0.5);
