            border-radius: 20px;
        }
        .meta-row {
            display: flex;
            justify-content: center;
            background: rgba(0,0,0,0.8);
            padding: 4px 8px;
            border-radius: 60px;
            margin: 3px auto;
            width: fit-content;
        }
        .timer-text {
            font-family: monospace;
            font-size: 11px;
            font-weight: 800;
            color: #00f5a0;
        }

        .nav-footer {
            display: flex;
            justify-content: center;
            gap: 5px;
        }
        .tiny-btn {
            background: rgba(0, 0, 0, 0.8);
            border: 1px solid var(--water-blue);
            border-radius: 30px;
            text-align: center;
            font-size: 8px;
            padding: 4px 10px;
            cursor: pointer;
            color: #ffffff;
            font-weight: bold;
        }

        /* ছোট-বড় করার বাটন */
        .resize-trigger {
            background: rgba(255, 77, 109, 0.3);
            border: 1px solid var(--loss-red);
            color: #ffffff;
            border-radius: 20px;
            font-size: 7.5px;
            padding: 2px 8px;
            cursor: pointer;
            font-weight: bold;
            margin-top: 4px;
            display: inline-block;
        }
    &lt;/style&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;iframe class=&quot;game-frame&quot; src=&quot;https://hgnice0.com/#/register?invitationCode=134451827863&quot;&gt;
    &lt;/iframe&gt;

    &lt;div id=&quot;main-panel&quot; class=&quot;drag-widget&quot;&gt;
      &lt;img id=&quot;mini-icon&quot; src=&quot;https://i.ibb.co/xSrPKpfV/IMG-20260605-174604-403.jpg&quot; alt=&quot;Mini Logo&quot; /&gt;

      &lt;div id=&quot;loginScreen&quot; class=&quot;screen&quot;&gt;
        &lt;div class=&quot;widget-header&quot;&gt;
          &lt;img class=&quot;brand-logo&quot; src=&quot;https://i.ibb.co/xSrPKpfV/IMG-20260605-174604-403.jpg&quot; alt=&quot;Logo&quot; /&gt;
          &lt;div class=&quot;brand-name&quot;&gt;SHANTO°𝑨𝑫𝑴𝑰𝑵&lt;/div&gt;
          &lt;div class=&quot;sub&quot;&gt;PREDICTION ENGINE&lt;/div&gt;
        &lt;/div&gt;
        &lt;input type=&quot;password&quot; id=&quot;passwordInput&quot; class=&quot;glass-input&quot; placeholder=&quot;PASSWORD&quot; /&gt;
        &lt;button class=&quot;btn-gold&quot; onclick=&quot;verifyPassword()&quot;&gt;ACCESS SYSTEM&lt;/button&gt;
        &lt;div class=&quot;nav-footer&quot;&gt;
          &lt;div class=&quot;tiny-btn&quot; onclick=&quot;openTelegram()&quot;&gt;📢 TELEGRAM&lt;/div&gt;
        &lt;/div&gt;
        &lt;div class=&quot;resize-trigger&quot; onclick=&quot;toggleMinimize(event)&quot;&gt;➖ MINIMIZE&lt;/div&gt;
      &lt;/div&gt;

      &lt;div id=&quot;serverScreen&quot; class=&quot;screen&quot;&gt;
        &lt;div class=&quot;widget-header&quot;&gt;
          &lt;img class=&quot;brand-logo&quot; src=&quot;https://i.ibb.co/xSrPKpfV/IMG-20260605-174604-403.jpg&quot; alt=&quot;Logo&quot; /&gt;
          &lt;div class=&quot;brand-name&quot;&gt;SHANTO ADMIN&lt;/div&gt;
          &lt;div class=&quot;sub&quot;&gt;SELECT GAME MODE&lt;/div&gt;
        &lt;/div&gt;
        &lt;button class=&quot;btn-gold&quot; onclick=&quot;selectGameMode('1M')&quot;&gt;⚡ WINGO 1 MIN&lt;/button&gt;
        &lt;button class=&quot;btn-outline&quot; onclick=&quot;selectGameMode('30S')&quot;&gt;🔥 WINGO 30 SEC&lt;/button&gt;
        &lt;div class=&quot;resize-trigger&quot; onclick=&quot;toggleMinimize(event)&quot;&gt;➖ MINIMIZE&lt;/div&gt;
      &lt;/div&gt;

      &lt;div id=&quot;engineScreen&quot; class=&quot;screen&quot;&gt;
        &lt;div class=&quot;widget-header&quot;&gt;
          &lt;img class=&quot;brand-logo&quot; src=&quot;https://i.ibb.co/xSrPKpfV/IMG-20260605-174604-403.jpg&quot; alt=&quot;Logo&quot; /&gt;
          &lt;div class=&quot;brand-name&quot;&gt;𝑴𝑨𝑹𝑰𝑨°𝑨𝑫𝑴𝑰𝑵&lt;/div&gt;
        &lt;/div&gt;
        &lt;div id=&quot;periodDisplay&quot; style=&quot;font-size: 8px; background: rgba(0,0,0,0.8); border-radius: 20px; padding: 2px; text-align: center; color: #ffffff; font-weight: bold; width:80%; margin:0 auto;&quot;&gt;PERIOD: ---&lt;/div&gt;
        &lt;div id=&quot;predictionValue&quot; class=&quot;prediction-big&quot; style=&quot;color:var(--gold)&quot;&gt;---&lt;/div&gt;
        &lt;div id=&quot;predictionNumber&quot; class=&quot;prediction-num&quot;&gt;NUM: --&lt;/div&gt;
        &lt;div class=&quot;meta-row&quot;&gt;
          &lt;span id=&quot;timerCountdown&quot; class=&quot;timer-text&quot;&gt;⏱️ 00s&lt;/span&gt;
        &lt;/div&gt;
        &lt;div class=&quot;resize-trigger&quot; onclick=&quot;toggleMinimize(event)&quot;&gt;➖ MINIMIZE&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;

    &lt;script&gt;
      const CONFIG = { password: &quot;M999&quot;, telegramLink: &quot;https://t.me/MARIA_TOP_123&quot; };
      const NUMBER_COLORS = { 0: { bg: 'linear-gradient(135deg, #9c27b0, #e91e63)', text: '#ffffff' }, 5: { bg: 'linear-gradient(135deg, #4caf50, #9c27b0)', text: '#ffffff' }, 1: { bg: '#ff4d6d', text: '#ffffff' }, 3: { bg: '#ff4d6d', text: '#ffffff' }, 7: { bg: '#ff4d6d', text: '#ffffff' }, 9: { bg: '#ff4d6d', text: '#ffffff' }, 2: { bg: '#00f5a0', text: '#000000' }, 4: { bg: '#00f5a0', text: '#000000' }, 6: { bg: '#00f5a0', text: '#000000' }, 8: { bg: '#00f5a0', text: '#000000' } };
      let currentMode = null, engineActive = false, apiBaseUrl = &quot;&quot;, lastIssueNumber = &quot;&quot;, currentPredictionObj = null, intervalID = null;              

      const loginScr = document.getElementById('loginScreen');
      const serverScr = document.getElementById('serverScreen');
      const engineScr = document.getElementById('engineScreen');
      const mainPanel = document.getElementById('main-panel');
      const periodSpan = document.getElementById('periodDisplay');
      const predictionDiv = document.getElementById('predictionValue');
      const predictionNumDiv = document.getElementById('predictionNumber');
      const timerSpan = document.getElementById('timerCountdown');

      window.toggleMinimize = function(e) {
          if(e) e.stopPropagation(); 
          mainPanel.classList.toggle('minimized');
      };

      function setActiveScreen(screenId) {
          loginScr.setAttribute('style', 'display: none !important');
          serverScr.setAttribute('style', 'display: none !important');
          engineScr.setAttribute('style', 'display: none !important');
          if(screenId === 'login') loginScr.setAttribute('style', 'display: block !important');
          else if(screenId === 'server') serverScr.setAttribute('style', 'display: block !important');
          else if(screenId === 'engine') engineScr.setAttribute('style', 'display: block !important');
      }

      window.verifyPassword = function() {
          const inputPass = document.getElementById('passwordInput').value.trim();
          if(inputPass === CONFIG.password) setActiveScreen('server');
          else alert(&quot;⛔ ACCESS DENIED! Wrong Password.&quot;);
      };

      window.openTelegram = function() { window.open(CONFIG.telegramLink, '_blank'); };

      window.selectGameMode = function(mode) {
          currentMode = mode;
          if(intervalID) clearInterval(intervalID);
          lastIssueNumber = &quot;&quot;; currentPredictionObj = null;
          apiBaseUrl = (mode === '1M') ? &quot;https://draw.ar-lottery01.com/WinGo/WinGo_1M/GetHistoryIssuePage.json?pageNo=1&amp;pageSize=50&quot; : &quot;https://draw.ar-lottery01.com/WinGo/WinGo_30S/GetHistoryIssuePage.json?pageNo=1&amp;pageSize=50&quot;;
          engineActive = true;
          setActiveScreen('engine');
          startPredictionEngine();
      };

      async function fetchAndAnalyze() {
          if(!engineActive || !apiBaseUrl) return;
          try {
              const response = await fetch(apiBaseUrl);
              const json = await response.json();
              if(!json || !json.data || !json.data.list || json.data.list.length === 0) return;
              const latestItem = json.data.list[0];      
              const currentIssue = latestItem.issueNumber;
              const currentNumber = latestItem.number;    
              const numericValue = parseInt(currentNumber, 10);
              const actualResult = (numericValue &gt;= 5) ? &quot;BIG&quot; : &quot;SMALL&quot;;
              lastIssueNumber = currentIssue;
              const nextIssueId = (BigInt(currentIssue) + 1n).toString();
              if(!currentPredictionObj || currentPredictionObj.id !== nextIssueId) {
                  let predictedBS = (Math.random() &lt; 0.12) ? ((actualResult === &quot;BIG&quot;) ? &quot;SMALL&quot; : &quot;BIG&quot;) : actualResult;
                  let luckyNum = (predictedBS === &quot;BIG&quot;) ? Math.floor(Math.random() * 5) + 5 : Math.floor(Math.random() * 5);
                  currentPredictionObj = { id: nextIssueId, bs: predictedBS, num: luckyNum };
                  predictionDiv.innerText = predictedBS;
                  predictionDiv.style.color = (predictedBS === &quot;BIG&quot;) ? &quot;var(--gold)&quot; : &quot;#ff6b8b&quot;;
                  const numStyle = NUMBER_COLORS[luckyNum] || { bg: '#fff', text: '#000' };
                  predictionNumDiv.innerText = `NUM: ${luckyNum}`;
                  predictionNumDiv.style.background = numStyle.bg;
                  predictionNumDiv.style.color = numStyle.text;
                  periodSpan.innerText = `PERIOD: ${nextIssueId.slice(-5)}`;
              }
          } catch(err) { console.warn(err); }
      }

      function startPredictionEngine() {
          if(intervalID) clearInterval(intervalID);
          fetchAndAnalyze();
          intervalID = setInterval(async () =&gt; {
              if(!engineActive) return;
              const seconds = new Date().getSeconds();
              let remaining = (currentMode === '1M') ? (60 - seconds) : ((30 - (seconds % 30)) % 30 || 30);
              timerSpan.innerText = `⏱️ ${remaining}s`;
              await fetchAndAnalyze();
          }, 1000);
      }

      function makeDraggable(element) {
          let isDragging = false, hasMoved = false;
          let startX = 0, startY = 0, initialLeft = 0, initialTop = 0;

          const onMouseMove = (e) =&gt; {
              if (!isDragging) return;
              let clientX = e.touches ? e.touches[0].clientX : e.clientX;
              let clientY = e.touches ? e.touches[0].clientY : e.clientY;

              if (Math.abs(clientX - startX) &gt; 4 || Math.abs(clientY - startY) &gt; 4) {
                  hasMoved = true;
              }

              element.style.left = Math.min(Math.max(0, initialLeft + (clientX - startX)), window.innerWidth - element.offsetWidth) + &quot;px&quot;;
              element.style.top = Math.min(Math.max(0, initialTop + (clientY - startY)), window.innerHeight - element.offsetHeight) + &quot;px&quot;;
          };

          const onMouseUp = (e) =&gt; {
              isDragging = false;
              document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp);
              document.removeEventListener('touchmove', onMouseMove); document.removeEventListener('touchend', onMouseUp);

              if (!hasMoved &amp;&amp; element.classList.contains('minimized')) {
                  toggleMinimize(e);
              }
          };

          const startDrag = (e) =&gt; {
              if(!element.classList.contains('minimized')) {
                  if(e.target.tagName === 'INPUT' || e.target.closest('button') || e.target.closest('.tiny-btn') || e.target.closest('.resize-trigger')) return;
              }

              isDragging = true;
              hasMoved = false;
              startX = e.touches ? e.touches[0].clientX : e.clientX;
              startY = e.touches ? e.touches[0].clientY : e.clientY;
              initialLeft = parseFloat(element.style.left) || element.offsetLeft;
              initialTop = parseFloat(element.style.top) || element.offsetTop;

              document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp);
              document.addEventListener('touchmove', onMouseMove, { passive: false }); document.addEventListener('touchend', onMouseUp);
          };

          element.addEventListener('mousedown', startDrag);
          element.addEventListener('touchstart', startDrag, { passive: MX12 });
      }

      makeDraggable(mainPanel);
      document.getElementById('passwordInput').addEventListener('keydown', function(e) { if(e.key === 'Enter') verifyPassword(); });
      window.addEventListener('DOMContentLoaded', () =&gt; { setActiveScreen('login'); });
    &lt;/script&gt;
  &lt;/body&gt;
&lt;/html&gt;
</code></pre>

Q: SELECT rows from a table which relate to qualifying ids in another table using CodeIgniter&#39;s query builder A: <p>Check your model.</p>
<pre><code>//QUERY ON MODEL
public function function_name($id){
$this-&gt;db-&gt;select('table_contain_name.id, table_contain_name.name, table_contain_name.address, table_contain_name.id_religion, table_religion.religion_name')
         -&gt;from('table_contain_name')
         -&gt;join('table_religion', 'table_religion.id=table_contain_name.id_religion)
         -&gt;where('table_contain_name.id', $id)
         -&gt;where('table_religion.religion_name', 'name of religion');
$data = $this-&gt;db-&gt;get();
return $data-&gt;result();
}
</code></pre>

Q: Error: signed modular JAR ...bcprov-jdk18on-1.84.jar is currently not supported, use --ignore-signing-information to suppress error A: <p>Thank you @Slaw for the answer. I changed the package phase to:</p>
<pre><code>&lt;execution&gt;
    &lt;id&gt;build-runtime-image&lt;/id&gt;
    &lt;phase&gt;package&lt;/phase&gt;
    &lt;goals&gt;
        &lt;goal&gt;jlink&lt;/goal&gt;
    &lt;/goals&gt;
    &lt;configuration&gt;
        &lt;mainClass&gt;b4synthesizer.ui.MVPPresenter&lt;/mainClass&gt;
        &lt;ignoreSigningInformation&gt;true&lt;/ignoreSigningInformation&gt;
    &lt;/configuration&gt;
&lt;/execution&gt;
</code></pre>
<p>and removed all the <code>jlinkExtraArgs</code> flags and now it is built correctly.</p>
